!function(){"use strict";window.__gospels={cats:[["birth","الميلاد والنسب"],["start","بداية الخدمة"],["miracles","معجزات وشفاءات"],["teach","تعليم وأمثال"],["road","في الطريق إلى أورشليم"],["week","الأسبوع الأخير"],["passion","الآلام والصلب"],["resur","القيامة وما بعدها"]],events:[{id:"genealogy",cat:"birth",title:"نسب المسيح",refs:{mt:["متى ١:١-١٧"],lk:["لوقا ٣:٢٣-٣٨"]},note:"متى يبدأ بإبراهيم نازلًا إلى المسيح، ولوقا يصعد من المسيح حتى آدم فيربطه بالبشرية كلها."},{id:"birth",cat:"birth",title:"ميلاد المسيح",refs:{mt:["متى ١:١٨-٢٥"],lk:["لوقا ٢:١-٢٠"]},note:"متى يروي الحدث من جهة يوسف، ولوقا من جهة مريم والرعاة والمذود."},{id:"baptist",cat:"start",title:"كرازة يوحنا المعمدان",refs:{mt:["متى ٣:١-١٢"],mk:["مرقس ١:١-٨"],lk:["لوقا ٣:١-١٨"],jn:["يوحنا ١:١٩-٢٨"]},note:"لوقا ينفرد بوصايا يوحنا للجموع والعشارين والجنود، ويوحنا الإنجيلي يركّز على شهادته أمام الكهنة واللاويين."},{id:"baptism",cat:"start",title:"معمودية يسوع",refs:{mt:["متى ٣:١٣-١٧"],mk:["مرقس ١:٩-١١"],lk:["لوقا ٣:٢١-٢٢"],jn:["يوحنا ١:٢٩-٣٤"]},note:"في متى يحاول يوحنا أن يمنعه، ولوقا يذكر أنه كان يصلّي، ويوحنا يروي شهادة المعمدان عن الروح الذي استقر عليه."},{id:"temptation",cat:"start",title:"التجربة في البرية",refs:{mt:["متى ٤:١-١١"],mk:["مرقس ١:١٢-١٣"],lk:["لوقا ٤:١-١٣"]},note:"مرقس يوجز في آيتين، ومتى ولوقا يفصّلان التجارب الثلاث بترتيب مختلف."},{id:"firstdisciples",cat:"start",title:"دعوة التلاميذ الأولين",refs:{mt:["متى ٤:١٨-٢٢"],mk:["مرقس ١:١٦-٢٠"],lk:["لوقا ٥:١-١١"],jn:["يوحنا ١:٣٥-٤٢"]},note:"في لوقا تأتي الدعوة بعد صيد السمك الكثير، وفي يوحنا يتبعه أندراوس وزميله بعد شهادة المعمدان عند الأردن."},{id:"levi",cat:"start",title:"دعوة متى (لاوي)",refs:{mt:["متى ٩:٩-١٣"],mk:["مرقس ٢:١٣-١٧"],lk:["لوقا ٥:٢٧-٣٢"]},note:"يُسمّى العشّار «متى» في إنجيله، و«لاوي» في مرقس ولوقا."},{id:"fasting",cat:"start",title:"سؤال عن الصوم",refs:{mt:["متى ٩:١٤-١٧"],mk:["مرقس ٢:١٨-٢٢"],lk:["لوقا ٥:٣٣-٣٩"]}},{id:"grainfields",cat:"start",title:"قطف السنابل في السبت",refs:{mt:["متى ١٢:١-٨"],mk:["مرقس ٢:٢٣-٢٨"],lk:["لوقا ٦:١-٥"]},note:"عبارة «السبت إنما جُعل لأجل الإنسان» ينفرد بها مرقس."},{id:"hand",cat:"start",title:"اليد اليابسة",refs:{mt:["متى ١٢:٩-١٤"],mk:["مرقس ٣:١-٦"],lk:["لوقا ٦:٦-١١"]}},{id:"twelve",cat:"start",title:"اختيار الاثني عشر",refs:{mt:["متى ١٠:١-٤"],mk:["مرقس ٣:١٣-١٩"],lk:["لوقا ٦:١٢-١٦"]},note:"لوقا يذكر أنه قضى الليل كله في الصلاة قبل أن يختارهم."},{id:"mother-in-law",cat:"miracles",title:"شفاء حماة بطرس",refs:{mt:["متى ٨:١٤-١٧"],mk:["مرقس ١:٢٩-٣٤"],lk:["لوقا ٤:٣٨-٤١"]},note:"الحدث في بيت بطرس بكفرناحوم، ثم يأتون إليه بمرضى المدينة عند الغروب."},{id:"leper",cat:"miracles",title:"تطهير الأبرص",refs:{mt:["متى ٨:١-٤"],mk:["مرقس ١:٤٠-٤٥"],lk:["لوقا ٥:١٢-١٦"]}},{id:"paralytic",cat:"miracles",title:"شفاء المفلوج",refs:{mt:["متى ٩:١-٨"],mk:["مرقس ٢:١-١٢"],lk:["لوقا ٥:١٧-٢٦"]},note:"مرقس ولوقا يرويان نزول المفلوج من السقف، أما متى فيختصر الحدث."},{id:"storm",cat:"miracles",title:"تهدئة العاصفة",refs:{mt:["متى ٨:٢٣-٢٧"],mk:["مرقس ٤:٣٥-٤١"],lk:["لوقا ٨:٢٢-٢٥"]},note:"مرقس ينفرد بذكر أنه كان نائمًا على وسادة في مؤخر السفينة."},{id:"gerasene",cat:"miracles",title:"المجنون في كورة الجدريين",refs:{mt:["متى ٨:٢٨-٣٤"],mk:["مرقس ٥:١-٢٠"],lk:["لوقا ٨:٢٦-٣٩"]},note:"متى يذكر مجنونين، ومرقس ولوقا يذكران واحدًا."},{id:"jairus",cat:"miracles",title:"ابنة يايرس والمرأة نازفة الدم",refs:{mt:["متى ٩:١٨-٢٦"],mk:["مرقس ٥:٢١-٤٣"],lk:["لوقا ٨:٤٠-٥٦"]}},{id:"beelzebul",cat:"miracles",title:"اتهام يسوع ببعلزبول",refs:{mt:["متى ١٢:٢٢-٣٠"],mk:["مرقس ٣:٢٠-٣٠"],lk:["لوقا ١١:١٤-٢٣"]}},{id:"centurion",cat:"miracles",title:"قائد المئة وخادمه",refs:{mt:["متى ٨:٥-١٣"],lk:["لوقا ٧:١-١٠"],jn:["يوحنا ٤:٤٦-٥٤"]},note:"يوحنا يروي حدثًا قريبًا (ابن خادم الملك في قانا)، ولا يتفق الدارسون على أنه الحدث نفسه."},{id:"nazareth",cat:"miracles",title:"رفض يسوع في الناصرة",refs:{mt:["متى ١٣:٥٣-٥٨"],mk:["مرقس ٦:١-٦"],lk:["لوقا ٤:١٦-٣٠"]},note:"لوقا يضع الحدث في بداية الخدمة، ويذكر قراءته من سفر إشعياء في المجمع."},{id:"sending",cat:"miracles",title:"إرسال الاثني عشر",refs:{mt:["متى ١٠:٥-١٥"],mk:["مرقس ٦:٧-١٣"],lk:["لوقا ٩:١-٦"]}},{id:"baptist-death",cat:"miracles",title:"استشهاد يوحنا المعمدان",refs:{mt:["متى ١٤:١-١٢"],mk:["مرقس ٦:١٤-٢٩"],lk:["لوقا ٩:٧-٩"]},note:"مرقس أكثرها تفصيلًا في وليمة هيرودس، ولوقا يكتفي بحيرة هيرودس."},{id:"feeding5000",cat:"miracles",title:"إشباع الخمسة آلاف",refs:{mt:["متى ١٤:١٣-٢١"],mk:["مرقس ٦:٣٠-٤٤"],lk:["لوقا ٩:١٠-١٧"],jn:["يوحنا ٦:١-١٥"]},note:"الأناجيل الأربعة تروي هذه المعجزة، ويوحنا ينفرد بذكر الغلام صاحب الأرغفة الخمسة والسمكتين."},{id:"water",cat:"miracles",title:"المشي على الماء",refs:{mt:["متى ١٤:٢٢-٣٣"],mk:["مرقس ٦:٤٥-٥٢"],jn:["يوحنا ٦:١٦-٢١"]},note:"متى ينفرد بمحاولة بطرس المشي على الماء."},{id:"feeding4000",cat:"miracles",title:"إشباع الأربعة آلاف",refs:{mt:["متى ١٥:٣٢-٣٩"],mk:["مرقس ٨:١-١٠"]}},{id:"bartimaeus",cat:"miracles",title:"شفاء الأعمى عند أريحا",refs:{mt:["متى ٢٠:٢٩-٣٤"],mk:["مرقس ١٠:٤٦-٥٢"],lk:["لوقا ١٨:٣٥-٤٣"]},note:"متى يذكر أعميين، ومرقس يسمّي الأعمى «بارتيماوس»."},{id:"beatitudes",cat:"teach",title:"التطويبات",refs:{mt:["متى ٥:١-١٢"],lk:["لوقا ٦:٢٠-٢٦"]},note:"تطويبات متى أكثر وتشير إلى الحالة الروحية («بالروح»)، وفي لوقا أربع تطويبات يقابلها أربعة ويلات."},{id:"lordsprayer",cat:"teach",title:"الصلاة الربانية",refs:{mt:["متى ٦:٩-١٣"],lk:["لوقا ١١:١-٤"]},note:"لوقا أقصر، ويقدّمها جوابًا لطلب التلميذ «علّمنا أن نصلّي»."},{id:"sower",cat:"teach",title:"مثل الزارع",refs:{mt:["متى ١٣:١-٩"],mk:["مرقس ٤:١-٩"],lk:["لوقا ٨:٤-٨"]}},{id:"sower-explained",cat:"teach",title:"تفسير مثل الزارع",refs:{mt:["متى ١٣:١٨-٢٣"],mk:["مرقس ٤:١٣-٢٠"],lk:["لوقا ٨:١١-١٥"]}},{id:"mustard",cat:"teach",title:"حبة الخردل",refs:{mt:["متى ١٣:٣١-٣٢"],mk:["مرقس ٤:٣٠-٣٢"],lk:["لوقا ١٣:١٨-١٩"]}},{id:"greatest-commandment",cat:"teach",title:"أعظم الوصايا",refs:{mt:["متى ٢٢:٣٤-٤٠"],mk:["مرقس ١٢:٢٨-٣٤"],lk:["لوقا ١٠:٢٥-٢٨"]},note:"في لوقا يأتي السؤال في سياق مختلف، وتتبعه قصة السامري الصالح."},{id:"peter-confession",cat:"road",title:"اعتراف بطرس",refs:{mt:["متى ١٦:١٣-٢٠"],mk:["مرقس ٨:٢٧-٣٠"],lk:["لوقا ٩:١٨-٢١"]},note:"متى ينفرد بكلمات «أنت بطرس وعلى هذه الصخرة أبني كنيستي»، ولوقا يذكر أنه كان يصلّي على انفراد."},{id:"first-prediction",cat:"road",title:"أول إعلان عن الآلام",refs:{mt:["متى ١٦:٢١-٢٨"],mk:["مرقس ٨:٣١-٣٨","مرقس ٩:١"],lk:["لوقا ٩:٢٢-٢٧"]}},{id:"transfiguration",cat:"road",title:"التجلّي",refs:{mt:["متى ١٧:١-١٣"],mk:["مرقس ٩:٢-١٣"],lk:["لوقا ٩:٢٨-٣٦"]},note:"لوقا يقول «نحو ثمانية أيام» بينما متى ومرقس يقولان «بعد ستة أيام»، وينفرد بموضوع حديثهم عن «خروجه» في أورشليم."},{id:"epileptic",cat:"road",title:"شفاء الولد المصروع",refs:{mt:["متى ١٧:١٤-٢١"],mk:["مرقس ٩:١٤-٢٩"],lk:["لوقا ٩:٣٧-٤٣"]},note:"مرقس أطولها، وفيه «أعن عدم إيماني»."},{id:"greatest",cat:"road",title:"من هو الأعظم؟",refs:{mt:["متى ١٨:١-٥"],mk:["مرقس ٩:٣٣-٣٧"],lk:["لوقا ٩:٤٦-٤٨"]}},{id:"rich-young",cat:"road",title:"الشاب الغني",refs:{mt:["متى ١٩:١٦-٣٠"],mk:["مرقس ١٠:١٧-٣١"],lk:["لوقا ١٨:١٨-٣٠"]},note:"في متى هو «شاب»، وفي لوقا «رئيس»، وفي مرقس يُذكر أن يسوع «نظر إليه وأحبه»."},{id:"zebedee",cat:"road",title:"طلب ابنَي زبدي",refs:{mt:["متى ٢٠:٢٠-٢٨"],mk:["مرقس ١٠:٣٥-٤٥"]},note:"في متى تتقدّم أمّهما بالطلب، وفي مرقس يتقدّمان بنفسيهما."},{id:"entry",cat:"week",title:"الدخول إلى أورشليم",refs:{mt:["متى ٢١:١-١١"],mk:["مرقس ١١:١-١١"],lk:["لوقا ١٩:٢٨-٤٠"],jn:["يوحنا ١٢:١٢-١٩"]}},{id:"temple",cat:"week",title:"تطهير الهيكل",refs:{mt:["متى ٢١:١٢-١٧"],mk:["مرقس ١١:١٥-١٩"],lk:["لوقا ١٩:٤٥-٤٨"],jn:["يوحنا ٢:١٣-٢٢"]},note:"يوحنا يضع الحدث في بداية خدمة المسيح، والإنجيليون الثلاثة في أسبوعه الأخير."},{id:"fig",cat:"week",title:"التينة التي لا تثمر",refs:{mt:["متى ٢١:١٨-٢٢"],mk:["مرقس ١١:١٢-١٤","مرقس ١١:٢٠-٢٦"]}},{id:"tenants",cat:"week",title:"مثل الكرّامين الأردياء",refs:{mt:["متى ٢١:٣٣-٤٦"],mk:["مرقس ١٢:١-١٢"],lk:["لوقا ٢٠:٩-١٩"]}},{id:"widow",cat:"week",title:"فلسا الأرملة",refs:{mk:["مرقس ١٢:٤١-٤٤"],lk:["لوقا ٢١:١-٤"]}},{id:"olivet",cat:"week",title:"علامات النهاية",refs:{mt:["متى ٢٤:١-١٤"],mk:["مرقس ١٣:١-١٣"],lk:["لوقا ٢١:٥-١٩"]}},{id:"anointing",cat:"week",title:"المرأة التي دهنت يسوع",refs:{mt:["متى ٢٦:٦-١٣"],mk:["مرقس ١٤:٣-٩"],jn:["يوحنا ١٢:١-٨"]},note:"يوحنا يذكر أنها مريم أخت لعازر، ولوقا يروي حدثًا قريبًا في بيت سمعان الفريسي (٧: ٣٦-٥٠)."},{id:"lastsupper",cat:"week",title:"العشاء الأخير",refs:{mt:["متى ٢٦:١٧-٣٠"],mk:["مرقس ١٤:١٢-٢٦"],lk:["لوقا ٢٢:٧-٢٣"]}},{id:"gethsemane",cat:"passion",title:"بستان جثسيماني",refs:{mt:["متى ٢٦:٣٦-٤٦"],mk:["مرقس ١٤:٣٢-٤٢"],lk:["لوقا ٢٢:٣٩-٤٦"]},note:"لوقا ينفرد بالملاك الذي يقوّيه وبالعرق الذي صار «كقطرات دم»."},{id:"arrest",cat:"passion",title:"القبض على يسوع",refs:{mt:["متى ٢٦:٤٧-٥٦"],mk:["مرقس ١٤:٤٣-٥٢"],lk:["لوقا ٢٢:٤٧-٥٣"],jn:["يوحنا ١٨:١-١٢"]}},{id:"peter-denial",cat:"passion",title:"إنكار بطرس",refs:{mt:["متى ٢٦:٦٩-٧٥"],mk:["مرقس ١٤:٦٦-٧٢"],lk:["لوقا ٢٢:٥٤-٦٢"],jn:["يوحنا ١٨:١٥-١٨","يوحنا ١٨:٢٥-٢٧"]},note:"لوقا ينفرد بأن الرب «التفت ونظر إلى بطرس»."},{id:"pilate",cat:"passion",title:"يسوع أمام بيلاطس",refs:{mt:["متى ٢٧:١١-٢٦"],mk:["مرقس ١٥:١-١٥"],lk:["لوقا ٢٣:١-٢٥"],jn:["يوحنا ١٨:٢٨-٤٠"]}},{id:"crucifixion",cat:"passion",title:"الصلب",refs:{mt:["متى ٢٧:٣٢-٤٤"],mk:["مرقس ١٥:٢١-٣٢"],lk:["لوقا ٢٣:٢٦-٤٣"],jn:["يوحنا ١٩:١٧-٢٧"]},note:"لوقا ينفرد بوعد اللص التائب «اليوم تكون معي في الفردوس»، ويوحنا بوصية الابن لأمه والتلميذ."},{id:"death",cat:"passion",title:"موت يسوع",refs:{mt:["متى ٢٧:٤٥-٥٦"],mk:["مرقس ١٥:٣٣-٤١"],lk:["لوقا ٢٣:٤٤-٤٩"],jn:["يوحنا ١٩:٢٨-٣٧"]}},{id:"burial",cat:"passion",title:"الدفن",refs:{mt:["متى ٢٧:٥٧-٦١"],mk:["مرقس ١٥:٤٢-٤٧"],lk:["لوقا ٢٣:٥٠-٥٦"],jn:["يوحنا ١٩:٣٨-٤٢"]},note:"يوحنا ينفرد بذكر نيقوديموس مع يوسف الرامي."},{id:"empty-tomb",cat:"resur",title:"القبر الفارغ",refs:{mt:["متى ٢٨:١-١٠"],mk:["مرقس ١٦:١-٨"],lk:["لوقا ٢٤:١-١٢"],jn:["يوحنا ٢٠:١-١٠"]}},{id:"appearance",cat:"resur",title:"الظهور للتلاميذ",refs:{lk:["لوقا ٢٤:٣٦-٤٩"],jn:["يوحنا ٢٠:١٩-٢٣"]}},{id:"commission",cat:"resur",title:"الإرسالية العظمى",refs:{mt:["متى ٢٨:١٦-٢٠"],mk:["مرقس ١٦:١٤-٢٠"],lk:["لوقا ٢٤:٤٤-٥٣"]}}]}}();